package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

/** Actual original archives/receipts and fictional retained outcomes; the composer performs no SQL. */
class SourceValueResolvedStageResultTest {
    SourceValuePartialResolutionTest f;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(boolean mixed)throws Exception{f=new SourceValuePartialResolutionTest(){@Override GenerationJdbcStoreTest database(){return SourceValueResolvedStageResultTest.this.database();}};f.setup(mixed);}
    void prepare(){for(int n=0;n<f.f.plan.chunks().size();n++)f.prepare(n);}
    void terminal(int part,String state){f.db.jdbc.update("UPDATE jobs SET state=?,call_count=?,revision=revision+1 WHERE id=?",state,"failed".equals(state)?3:0,f.f.plan.chunks().get(part).rootId());}
    @Test void SparseAppliedValueKeepsOriginalPartsDecisionsAndBothStageOmissions()throws Exception{
        setup(true);prepare();int last=f.f.plan.chunks().size()-1;for(int n=0;n<last;n++)terminal(n,"failed");f.outcomes.complete(last);var snapshot=f.read();int count=f.db.count("1=1"),calls=f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);
        var result=SourceValueStageResult.createResolved(snapshot);var json=CanonicalJson.parse(result.json());int applied=f.f.plan.chunks().getLast().itemIds().size();
        assertEquals("source-value-stage-result-v2",json.get("schema_version").asText());assertEquals("partial",json.get("coverage_state").asText());assertEquals(201,json.get("accepted").asInt());assertEquals(201,json.get("decisions").size());assertEquals(200,json.get("eligible_count").asInt());assertEquals(applied,json.get("applied_member_count").asInt());assertEquals(200-applied,json.get("unapplied_member_count").asInt());assertEquals(f.f.plan.chunks().size(),json.get("resolutions").size());assertEquals(1,json.get("fragments").size());assertEquals(last,json.get("fragments").get(0).get("stage_part").asInt());assertEquals(last,result.fragments().getFirst().stagePart());assertEquals(applied,result.members().size());
        for(int n=0;n<f.f.plan.chunks().size();n++){var row=json.get("resolutions").get(n);assertEquals(10,row.size());assertEquals(f.f.plan.chunks().get(n).rootId(),row.get("root_id").asText());assertEquals(JsonMapper.shared().valueToTree(f.f.plan.chunks().get(n).itemIds()),row.get("item_ids"));}
        assertEquals(CanonicalJson.parse(f.f.plan.scope().stageContextJson()),json.get("stage_context"));assertEquals(1,json.get("stage_context").get(FrozenSourceDedupDependency.FIELD).get("stage_result").get("unapplied_member_count").asInt());assertTrue(json.get("missing").valueStream().anyMatch(n->n.get("reason").asText().equals("dedup_failed")));assertEquals(last,json.get("missing").valueStream().filter(n->n.get("reason").asText().equals("value_failed")).count());assertFalse(json.get("missing").valueStream().anyMatch(n->n.get("reason").asText().equals("collection_partial")));assertSorted(json);
        assertEquals(result.hash(),CanonicalJson.hash(CanonicalJson.Domain.CONTENT,json));assertEquals(result.hash(),CanonicalJson.parse(result.observationKeyJson()).get("result_hash").asText());assertEquals(result.json(),SourceValueStageResult.createResolved(snapshot).json());assertEquals(count,f.db.count("1=1"));assertEquals(calls,f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertThrows(UnsupportedOperationException.class,()->result.members().clear());assertThrows(UnsupportedOperationException.class,()->result.fragments().clear());assertThrows(UnsupportedOperationException.class,()->result.decisions().clear());assertFalse(result.toString().contains("Fictional"));
    }
    @Test void AllValueFailuresKeepOriginalEligibleCountAndEveryExplicitFailureReason()throws Exception{
        setup(true);prepare();for(String state:List.of("failed","cancelled","discarded","superseded")){for(int n=0;n<f.f.plan.chunks().size();n++)terminal(n,state);var result=SourceValueStageResult.createResolved(f.read());var json=CanonicalJson.parse(result.json());assertEquals(200,json.get("eligible_count").asInt());assertEquals(200,json.get("unapplied_member_count").asInt());assertEquals(0,json.get("applied_member_count").asInt());assertTrue(result.fragments().isEmpty());assertTrue(result.members().isEmpty());assertTrue(json.get("fragments").isEmpty());assertEquals(f.f.plan.chunks().size(),json.get("missing").valueStream().filter(n->n.get("reason").asText().equals("value_"+state)).count());assertEquals(201,result.decisions().size());assertSorted(json);}
    }
    @Test void ZeroValuePlanStillContainsTheOriginalFailedDedupMember()throws Exception{
        setup(false);var result=SourceValueStageResult.createResolved(f.read());var json=CanonicalJson.parse(result.json());assertEquals("source-value-stage-result-v2",json.get("schema_version").asText());assertEquals(1,json.get("accepted").asInt());assertEquals(1,json.get("decisions").size());assertEquals(0,json.get("eligible_count").asInt());assertEquals(0,json.get("applied_member_count").asInt());assertEquals(0,json.get("unapplied_member_count").asInt());assertEquals(1,json.get("missing").size());assertEquals("dedup_failed",json.get("missing").get(0).get("reason").asText());assertTrue(json.get("resolutions").isEmpty());assertTrue(result.fragments().isEmpty());assertEquals(1,json.get("stage_context").get(FrozenSourceDedupDependency.FIELD).get("stage_result").get("unapplied_member_count").asInt());
    }
    @Test void AllAppliedValueStillPreservesOriginalDedupPartialCoverage()throws Exception{
        setup(true);prepare();for(int n=0;n<f.f.plan.chunks().size();n++)f.outcomes.complete(n);var result=SourceValueStageResult.createResolved(f.read());var json=CanonicalJson.parse(result.json());assertEquals("source-value-stage-result-v2",json.get("schema_version").asText());assertEquals(200,json.get("applied_member_count").asInt());assertEquals(0,json.get("unapplied_member_count").asInt());assertEquals(f.f.plan.chunks().size(),result.fragments().size());assertEquals(1,json.get("missing").size());assertEquals("dedup_failed",json.get("missing").get(0).get("reason").asText());
    }
    @Test void LegacyAllAppliedAndZeroDelegateExactBytesAndLegacyFailuresBecomeValueOmissions()throws Exception{
        SourceAnalysisParentStepTest legacy=new SourceAnalysisParentStepTest(){@Override GenerationJdbcStoreTest database(){return SourceValueResolvedStageResultTest.this.database();}};legacy.completedP1();legacy.step.step(legacy.candidate(legacy.handoffs.ref.ownerId()));var child=legacy.candidate(legacy.handoffs.read().p2Owner());legacy.step.step(child);var ref=legacy.reference(child.id());legacy.completeP2(ref);var reader=new SourceDedupResolvedStageResultTest();reader.f=legacy;var snapshot=reader.snapshot(ref);var proofs=snapshot.fragments().stream().map(n->n.value().proof()).toList();var expected=SourceValueStageResult.create(snapshot.plan(),snapshot.universe(),ref,proofs);var actual=SourceValueStageResult.createResolved(snapshot);assertEquals(expected.json(),actual.json());assertEquals(expected.observationKeyJson(),actual.observationKeyJson());
        // A separate unfinished legacy root proves v2 can originate from P2 failure alone.
        legacy=new SourceAnalysisParentStepTest(){@Override GenerationJdbcStoreTest database(){return SourceValueResolvedStageResultTest.this.database();}};legacy.completedP1();legacy.step.step(legacy.candidate(legacy.handoffs.ref.ownerId()));child=legacy.candidate(legacy.handoffs.read().p2Owner());legacy.step.step(child);ref=legacy.reference(child.id());reader.f=legacy;var pending=reader.snapshot(ref);assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolved(pending));for(var chunk:pending.plan().chunks())legacy.db.jdbc.update("UPDATE jobs SET state='failed',call_count=3,revision=revision+1 WHERE id=?",chunk.rootId());var failed=CanonicalJson.parse(SourceValueStageResult.createResolved(reader.snapshot(ref)).json());assertEquals("source-value-stage-result-v2",failed.get("schema_version").asText());assertEquals("partial",failed.get("stage_context").get("coverage_state").asText());assertEquals(1,failed.get("missing").valueStream().filter(n->n.get("kind").asText().equals("source_run")&&n.get("id").asText().equals(failed.get("run_id").asText())&&n.get("reason").asText().equals("collection_partial")).count());assertEquals(pending.plan().chunks().size(),failed.get("missing").valueStream().filter(n->n.get("reason").asText().equals("value_failed")).count());assertEquals(Set.of("collection_partial","value_failed"),new HashSet<>(failed.get("missing").valueStream().map(n->n.get("reason").asText()).toList()));assertSorted(failed);
        legacy=new SourceAnalysisParentStepTest(){@Override GenerationJdbcStoreTest database(){return SourceValueResolvedStageResultTest.this.database();}};legacy.newSource();legacy.db.jdbc.update("UPDATE source_run_items SET effective_valid=0");var parent=legacy.candidate(legacy.p1.collection.intentId());legacy.step.step(parent);legacy.step.step(legacy.candidate(parent.id()));var instance=legacy;var relation=legacy.read(()->instance.handoffs.metadata.read(parent.id()));child=legacy.candidate(relation.p2Owner());legacy.step.step(child);ref=legacy.reference(child.id());reader.f=legacy;snapshot=reader.snapshot(ref);assertTrue(snapshot.fragments().isEmpty());expected=SourceValueStageResult.create(snapshot.plan(),snapshot.universe(),ref,List.of());actual=SourceValueStageResult.createResolved(snapshot);assertEquals(expected.json(),actual.json());assertEquals(expected.hash(),actual.hash());
    }
    @Test void PendingWrongStageAndBoundedCapacityCannotBecomeAResolvedValueResult()throws Exception{
        setup(true);var missing=f.read();assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolved(missing));prepare();var pending=f.read();assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolved(pending));assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolved(f.authority.f.snapshot(f.authority.f.ref)));
        for(int n=0;n<f.f.plan.chunks().size();n++)terminal(n,"failed");var settled=f.read();assertThrows(GenerationFlowService.CapacityGuarded.class,()->SourceValueStageResult.createResolvedWithinCapacity(settled,64));assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolvedWithinCapacity(settled,0));assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolvedWithinCapacity(settled,SourceValueStageResult.MAX_BYTES+1));assertThrows(RuntimeException.class,()->SourceValueStageResult.createResolved(null));assertDoesNotThrow(()->SourceValueStageResult.createResolved(settled));
    }
    static void assertSorted(tools.jackson.databind.JsonNode json){var keys=json.get("missing").valueStream().map(n->n.get("kind").asText()+"/"+n.get("id").asText()+"/"+n.get("reason").asText()).toList();assertEquals(keys.stream().sorted().toList(),keys);assertEquals(keys.size(),new HashSet<>(keys).size());}
}
